/**
 * Retirements stamped at or before this instant have been released: a hold
 * ends at exactly `ORG_SLUG_HOLD_DAYS` days after the rename (ADR 0005 §3).
 * ISO-8601 UTC strings order the same way the instants do.
 */
function holdCutoff(now: Date): string {
  return toIsoTimestamp(new Date(now.getTime() - ORG_SLUG_HOLD_DAYS * MS_PER_DAY));
}

/**
 * The one rule that turns a slug into a workspace (ADR 0005 §3): the live
 * workspace whose current slug it is, otherwise the live workspace that
 * retired it less than `ORG_SLUG_HOLD_DAYS` days ago. The session layer and
 * every other lookup come through here.
 */
export async function findOrgBySlug(slug: string): Promise<Organization | null> {
  const db = getDb();

  const current = db
    .select()
    .from(organizations)
    .where(and(eq(organizations.slug, slug), isNull(organizations.archivedAt)))
    .get();
  if (current) return toOrganization(current);

  const held = db
    .select({ org: organizations })
    .from(organizationRetiredSlugs)
    .innerJoin(
      organizations,
      eq(organizations.id, organizationRetiredSlugs.orgId),
    )
    .where(
      and(
        eq(organizationRetiredSlugs.slug, slug),
        gt(organizationRetiredSlugs.retiredAt, holdCutoff(new Date())),
        isNull(organizations.archivedAt),
      ),
    )
    .get();
  return held ? toOrganization(held.org) : null;
}

/**
 * Whether `orgId` may take `slug` (ADR 0005 §2): no other workspace — live or
 * deleted — has it as its current slug, and no other workspace holds it
 * retired. A slug the workspace retired itself is always available to it.
 */
export async function isOrgSlugAvailable(
  orgId: OrgId,
  slug: string,
): Promise<boolean> {
  const db = getDb();

  const current = db
    .select({ id: organizations.id })
    .from(organizations)
    .where(and(eq(organizations.slug, slug), ne(organizations.id, orgId)))
    .get();
  if (current) return false;

  const held = db
    .select({ orgId: organizationRetiredSlugs.orgId })
    .from(organizationRetiredSlugs)
    .where(
      and(
        eq(organizationRetiredSlugs.slug, slug),
        ne(organizationRetiredSlugs.orgId, orgId),
        gt(organizationRetiredSlugs.retiredAt, holdCutoff(new Date())),
      ),
    )
    .get();
  return !held;
}

