  const a = await createTenant("alpha");
  const b = await createTenant("bravo");
  const seen: unknown[] = [];
  subscribe("organization.slug_changed", (p) => { seen.push(p); });
  await expect(renameOrganizationSlug(a.actors.member, { orgId: a.org.id, slug: "alpha2" })).rejects.toBeInstanceOf(PermissionDeniedError);
  await expect(renameOrganizationSlug(a.actors.admin, { orgId: a.org.id, slug: "bravo" })).rejects.toBeInstanceOf(InvalidSlugError);
  await expect(renameOrganizationSlug(a.actors.admin, { orgId: a.org.id, slug: "settings" })).rejects.toBeInstanceOf(InvalidSlugError);
  expect(await renameOrganizationSlug(a.actors.admin, { orgId: a.org.id, slug: "alpha" })).toEqual(a.org);
  expect(seen).toHaveLength(0);
  const r = await renameOrganizationSlug(a.actors.admin, { orgId: a.org.id, slug: "alpha2" });
  expect(r).toEqual({ ...a.org, slug: "alpha2" });
  expect(seen).toHaveLength(1);
  expect((await resolveOrgBySlug("alpha"))?.id).toBe(a.org.id);
  expect((await resolveOrgBySlug("alpha2"))?.slug).toBe("alpha2");
