  expect(await orgRepo.findOrgBySlug("alpha")).toBeNull();
  expect((await orgRepo.findOrgBySlug("alpha2"))?.id).toBe(a.org.id);
  expect((await renameOrganizationSlug(b.actors.owner, { orgId: b.org.id, slug: "alpha" })).slug).toBe("alpha");
  expect((await orgRepo.findOrgBySlug("bravo"))?.id).toBe(b.org.id);
  // rename back
  await renameOrganizationSlug(a.actors.owner, { orgId: a.org.id, slug: "alpha2" });
  expect((await orgRepo.findOrgBySlug("alpha3"))?.id).toBe(a.org.id);
